contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // params: receiver can be any address, amount is the requested transfer amount
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // This test contract deployed c, so it is the owner. Ensure we have enough ether to optionally refund later.
        require(address(this).balance >= 0);

        // Observe c's balance before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // Make the state-changing call as owner (this contract is owner)
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: if call succeeded, the transferred amount cannot exceed the contract's prior balance
        // and balances reflect that no more than 'amount' left c; if call reverted then balances unchanged.
        assert(
            (reverted && afterC == beforeC && afterThis == beforeThis)
            || (!reverted && beforeC >= amount && beforeC - afterC == amount && (afterThis == beforeThis || afterThis == beforeThis + amount))
        );
    }

    receive() external payable { }
}

